export const stages = [
  {id:'scan', number:'01', title:'Scan the horizon', short:'Scan', verb:'Notice what is changing', minutes:35, description:'Find emerging patterns. Ask what could sustain, disrupt or reverse them.', output:'An evidenced set of trends, with an outlook and uncertainties.', instructions:['Split into groups, one for each letter of STEEP (Social, Technological, Economic, Environmental and Political), or your preferred horizon scanning framework.','Identify sustained or emerging changes relevant to the shared question.','Capture the direction, evidence, uncertainty and outlook for each trend. These terms are defined in the worksheet.','Explore the mechanisms through which the change could create humanitarian consequences.']},
  {id:'prioritise', number:'02', title:'Prioritise the trends', short:'Prioritise', verb:'Decide what deserves attention', minutes:30, description:'Compare possible consequences and their likelihood.', output:'Group pitches, a recorded vote and a watch list of important outliers.', instructions:['Place trends on an impact–likelihood matrix and record the reasoning.','Each group pitches two priority trends to everybody else. What about the trend, its outlook and humanitarian significance means it deserves their vote?','Everybody individually dot-votes on their highest-priority trends. Give each participant five dots. They can place more than one dot on a single trend, if they wish.','Retain low-likelihood, high-impact possibilities on a separate watch list.']},
  {id:'narrative', number:'03', title:'Shape the narrative', short:'Connect', verb:'Find the story between the signals', minutes:20, description:'Connect drivers, trends and consequences into a coherent explanation.', output:'An agreed shortlist and an outline of the briefing’s overarching story.', instructions:['Review the highly ranked trends together; do not simply accept the vote at face value.','Identify common drivers, overlapping trends and shared consequences.','Ask what might amplify, constrain or counteract another trend.','Agree the final shortlist of trends and sketch the causal story, checking for missing perspectives.']},
  {id:'write', number:'04', title:'Write the briefing', short:'Write', verb:'Turn analysis into understanding', minutes:45, description:'Bring the evidence and implications together in a consistent structure.', output:'Trend drafts, an introduction and a conclusion that form one coherent story.', instructions:['Create new groups, one for each shortlisted trend.','Use the six-part structure: trend summary, consequences, actors, evidence, uncertainty and indicators.','Assign a separate small group to the introduction, conclusion and overall narrative.','Make the implications relevant to the audience.']},
  {id:'review', number:'05', title:'Challenge and refine', short:'Refine', verb:'Make the thinking stronger', minutes:30, description:'Test assumptions, strengthen the story and rehearse the whole briefing.', output:'A challenged, edited briefing with uncertainties and follow-through made clear.', instructions:['Present the analysis to other groups for constructive challenge.','Use the red-team prompt questions in the worksheet to test evidence, causality and overlooked perspectives.','Appoint a lead editor to remove duplication and align terminology and uncertainty statements.','Rehearse the complete briefing if presenting orally.']}
];

export const lessons = [
  {id:'purpose', section:'Start here', source:1, title:'Start with a decision', deck:'Anticipatory analysis helps people act before events unfold.', why:'The value of looking ahead is in the decisions it improves. A credible account of what might happen gives people time to prepare, influence outcomes and imagine alternatives.', actions:['Articulate the decisions or preparedness activities your analysis could inform.'], output:'A clear purpose that connects future change to a real decision.', deeper:[['Three reasons to look ahead','Operational readiness means recognising emerging risks and testing preparations. Humanitarian influence means identifying consequences early enough to inform policy, diplomacy, funding and practice. Humanitarian imagination means considering alternative futures in which needs are reduced and collective action succeeds.'],['Timeliness matters','A useful analysis delivered while there is still time to act can be more valuable than a comprehensive one delivered too late. Anticipation combines evidence, imagination, judgement and practical knowledge.']], tip:'Return to the shared question whenever discussion becomes a catalogue of current crises.'},
  {id:'audience', section:'Start here', source:2, title:'Know who needs to use this', deck:'Different responsibilities need different implications.', why:'An operations director, humanitarian diplomat and preparedness specialist may read the same evidence and face very different decisions.', actions:['Identify the intended audience, their responsibilities and the decisions they may face.','Agree a time horizon, or several horizons where useful, and make them explicit.','Distinguish findings, humanitarian implications, audience considerations and specific recommendations.'], output:'An audience and decision brief that the whole group can work from.', deeper:[['Four different outputs','Findings describe what is happening or might happen. Humanitarian implications explain what that could mean for needs, access, capabilities and operations. Considerations pose relevant questions for different audiences. Recommendations identify specific actions and are usually best developed with the people expected to implement them.'],['One evidence base, two products','A shared briefing can focus on findings and implications. An organisation can then develop a tailored internal product with operational recommendations. Embedded analysts can help translate the evidence into local decisions.'],['What audiences often need','Diverse perspectives, help navigating uncertainty, timely intelligence, opportunities to test plans and clear implications for their responsibilities.']], tip:'Ask participants to finish the sentence: “This will help our audience decide whether, when or how to…”'},
  {id:'scan', section:'Five-stage method', source:3, title:'Scan the horizon', deck:'Look for patterns of change, then reason about what comes next.', why:'A list of existing problems does not show how humanitarian risks may change. Anticipatory analysis will connect observed developments to their potential consequences.', actions:stages[0].instructions, output:stages[0].output, deeper:[['What belongs on a trend card?','Record the trend, its direction, evidence with sources and dates, uncertainties, and the outlook. Direction may be accelerating, continuing, slowing, reversing or difficult to assess.'],['Move from description to outlook','Consider scheduled developments such as elections, funding decisions and seasonal events. Examine underlying drivers, potential disruptions, known unknowns and mechanisms that could create humanitarian consequences.'],['Separate evidence and judgement','Observed data and documented developments describe the past and present. An assessment of what may happen next is a judgement. Record both, while making their different status and confidence clear.']], tip:'A longstanding vulnerability matters when something is changing that could alter exposure, coping capacity or consequences.'},
  {id:'prioritise', section:'Five-stage method', source:3, title:'Prioritise the trends', deck:'Use a matrix to support discussion, then explain your choices.', why:'Focus on the trends that are most likely to have the greatest consequences.', actions:stages[1].instructions, output:stages[1].output, deeper:[['Assess the same proposition','A trend may already be happening while its future acceleration remains uncertain. Write down the specific development, consequence and time horizon being assessed before assigning likelihood.'],['Think beyond a single impact label','Discuss who may be affected, the scale and severity of possible consequences, and whether communities’ or humanitarian organisations’ capacities could be overwhelmed.'],['The vote is an input','The matrix and dot-vote structure judgement. They are not an objective risk model. Group composition, knowledge gaps and biases can influence the result. Retain important low-likelihood, high-impact possibilities on a watch list.']], tip:'Each group pitches two trends. Ask: what is changing, why now, what consequences, and why this rather than another trend?'},
  {id:'narrative', section:'Five-stage method', source:3, title:'Shape the narrative', deck:'The shortlist should explain a changing situation.', why:'A coherent explanation of how risks connect is more useful than unrelated mini-analyses. Several trends may be expressions of the same driver.', actions:stages[2].instructions, output:stages[2].output, deeper:[['Look for relationships between trends','Ask whether one trend is a consequence of another, whether several lead to similar impacts and whether one could amplify or constrain another. Combine or drop items where this improves clarity.'],['Sketch a causal pathway','Map a driver to a trend and then to possible humanitarian consequences. Use the map to expose missing steps and assumptions. A neat diagram does not itself prove causality.']], tip:'Before agreeing the shortlist, invite a perspective that the voting process may have overlooked.'},
  {id:'write', section:'Five-stage method', source:3, title:'Write the briefing', deck:'Use a shared structure so many voices become one clear story.', why:'Consistent contributions make the final briefing easier to integrate. The opening and conclusion must connect the parts to the audience’s needs.', actions:stages[3].instructions, output:stages[3].output, deeper:[['The six-part structure','Summarise the change and outlook. Explain humanitarian consequences: what, to whom, where, when and through which pathways. Identify key actors. State the evidence. Explore uncertainty and competing interpretations. Specify observable indicators that could change the assessment.'],['Open with what is at stake','Use a compelling question or tension that explains why the audience should care now. The conclusion should draw together implications, uncertainties and what to monitor, rather than repeat the summaries.'],['Tailor without overreaching','Where useful, add questions or considerations for operations, preparedness, policy or diplomacy specialists. Avoid unsupported recommendations for people who have not helped develop them.']], tip:'Give a small group responsibility for the overarching narrative while other groups draft individual trends.'},
  {id:'review', section:'Five-stage method', source:3, title:'Challenge and refine', deck:'Constructive challenge makes uncertainty and assumptions visible.', why:'Plausibility can be mistaken for probability, and a persuasive story can conceal weak evidence or a missing causal link.', actions:stages[4].instructions, output:stages[4].output, deeper:[['Edit beyond fact-checking','Review the flow, remove duplication and align terminology and uncertainty statements. A lead editor gives the final product a consistent voice.'],['Use visuals as thinking tools','Well-designed visuals can clarify causal relationships and uncertainty. Involve a designer early when feasible, rather than treating graphics as decoration at the end.'],['Rehearse the whole briefing','An oral rehearsal tests whether the audience can follow the complete argument. Use it as another opportunity to challenge the analysis.']], tip:'Invite participants to challenge the reasoning, not defend their authorship. Make alternative interpretations welcome.'},
  {id:'collaboration', section:'Facilitate a workshop', source:4, title:'Use the group where it adds value', deck:'Not everyone needs to contribute equally to every stage.', why:'Collaboration takes time. Its value comes from different expertise and perspectives, not simply from adding more people.', actions:['Bring a diverse group into scanning, interpretation, consequence mapping and challenge.','Consider a smaller writing and editorial team for the final product.','Choose participants deliberately, including relevant local knowledge and affected-community perspectives where appropriate.'], output:'Clear roles and a participant mix that adds analytical value.', deeper:[['Choose capabilities, not a headcount','Depending on the question, include subject specialists, quantitative analysts, regional experts, operational experience, foresight practitioners and communications skills. There is no universal optimal group size.'],['Make the process legible','Explain each stage’s purpose, instructions, time available, expected output and transition. Reassure participants how their contributions will come together. This guide describes a five-stage method for analysing trends that has been tested with 21 analysts over approximately three hours; treat it as an example, not a required format.']], tip:'Keep asking whose knowledge is missing and which task most benefits from the people in the room.'},
  {id:'ai', section:'Facilitate a workshop', source:4, title:'Use AI to make room for thinking', deck:'Automate some information processing but keep judgement firmly with humans.', why:'Evidence gathering and synthesis can consume the time a group needs for debate and interpretation. AI can help, but seemingly convincing outputs may still be unsupported.', actions:['Use shared research questions to guide evidence gathering before a workshop.','Consider AI support to search for data and evidence, summarise sources, analyse and compare trends, and explore hypotheses.','Verify claims, citations and syntheses against original sources and challenge the outputs.'], output:'A common evidence starting point that people have checked.', deeper:[['Useful applications','AI can suggest gaps, competing interpretations, causal pathways and indicators. It can compare sources, identify overlap, challenge assumptions and assist with editing or visualisation.'],['Keep the limits visible','AI can reproduce bias, omit perspectives and produce convincing explanations without adequate support. Human expertise and judgement remain essential.']], tip:'Spend time saved on discussing uncertainties and consequences, rather than producing more unchecked material.'},
  {id:'care', section:'Facilitate a workshop', source:5, title:'Make room for people too', deck:'Future crises are not abstract for everyone in the room.', why:'Exploring plausible crises can be distressing or retraumatising, especially for people who have experienced similar events.', actions:['Use trauma-informed facilitation and acknowledge the human experience behind scenarios.','Provide opportunities to pause or step away.','Consider participants’ needs when choosing examples, pacing and discussion formats.'], output:'A workshop that takes psychological care seriously.', deeper:[['Build care into the process','The guide places care alongside analytical rigour. Keep participation respectful and avoid treating distressing scenarios as detached intellectual exercises.']], tip:'Make pauses available throughout the session, rather than relying only on the scheduled break.'},
  {id:'communicate', section:'Communicate and continue', source:5, title:'Tell a credible, useful story', deck:'Help your audience understand why the analysis matters to them.', why:'Good analysis only helps if it reaches people in a form they can understand and use. A parade of risks can obscure the relationships and opportunities to influence outcomes.', actions:['Connect developments, possible consequences and opportunities for action.','Choose a format suited to the audience: a short briefing, visual presentation, discussion or interactive product.','Use concrete examples, meaningful visuals and questions tied to responsibilities.'], output:'A communication approach designed around the audience.', deeper:[['Be transparent about uncertainty','Distinguish what is observed, inferred, projected and uncertain. Use models such as forecasts only when they help answer the question and support decisions; sophisticated forecasting is not always necessary.'],['Build a predictable rhythm','Regular publication can build trust and two-way exchange.'],['Find allies to amplify your message', 'Identify people who might help your findings reach decision-makers beyond your network.']], tip:'Test the briefing’s opening with someone outside the drafting group: can they explain why it matters now?'},
  {id:'network', section:'Communicate and continue', source:6, title:'Turn one workshop into shared learning', deck:'The relationships can be as valuable as the briefing.', why:'Analysts often examine the same sources and related questions, while no individual has a complete picture. Networks can reduce duplication and expose blind spots.', actions:['Share appropriate sources, methods, lessons and unanswered questions.','Create opportunities for peer review, joint analysis, training and experimentation.','Agree expectations for attribution, quality, sensitivity and information security.'], output:'A practical next step for maintaining the analytical network.', deeper:[['Possible shared infrastructure','Your could create spaces for a shared ongoing horizon scan, reusable driver files, a source and indicator library, and potential topics to explore in future.'],['A team of teams','Organisations can retain their priorities and capabilities while contributing to common knowledge and products. Diverse networks can identify under-analysed topics and broaden access to expertise.']], tip:'End with a concrete agreement about who will share, discuss, challenge or update the analysis.'},
  {id:'follow-through', section:'Communicate and continue', source:8, title:'Judge success by what becomes possible', deck:'The test is whether people are better able to act in time.', why:'Anticipatory analysis helps humanitarian actors prepare for different ways the future could unfold. Collaboration is useful when it improves that capacity.', actions:['Ask whether the audience recognised what might happen and what was at stake.','Review whether the analysis helped people become better prepared to act.','Use feedback to improve the next cycle’s evidence, participation and communication.'], output:'A learning loop between the analysis and the people who use it.', deeper:[['Keep the purpose in view','Be deliberate about when collaboration adds value, who participates and how outputs reach decision-makers. Combine evidence, imagination, critical judgement and practical knowledge of humanitarian action.'],['Reflect and continuously improve', 'Track the questions audiences ask and use them to improve future anticipatory products. Seek feedback from your audiences.']], tip:'A completed briefing is an output. Better preparedness and better decisions are the purpose.'}
];

export const checklist = [
 ['Purpose','Is it clear what decisions or forms of preparedness this analysis could inform?'],
 ['Audience','Do we understand who will use it, and have we made the implications relevant to them?'],
 ['Time horizon','Is the period under consideration explicit and consistent?'],
 ['Evidence','Can our audience distinguish observed trends from assumptions and judgements about the future?'],
 ['Causality','Have we explained how developments might generate humanitarian consequences?'],
 ['Uncertainty','Have we surfaced competing interpretations, major knowledge gaps and alternative trajectories?'],
 ['Blind spots','Have we challenged our assumptions and included sufficiently diverse perspectives?'],
 ['Capacity','Have we considered the ability of communities and humanitarian actors to anticipate, cope and respond?'],
 ['Narrative','Does the briefing tell a coherent, memorable and credible story rather than simply listing risks?'],
 ['Implications','Will our audience understand what the analysis could mean for their responsibilities, without inappropriate or unsupported recommendations?'],
 ['Monitoring','Have we identified meaningful indicators that would change our assessment?'],
 ['Follow-through','Do we know how the analysis will be shared, discussed, challenged and updated?']
];
export const redTeam = [
 ['Test the evidence','Is the evidence sufficiently credible and current?','Trace important claims back to their original sources.'],
 ['Test the probability','Are we confusing a plausible future with a probable one?','Name the proposition and distinguish possibility from assessed likelihood.'],
 ['Test the causal link','Have we explained the pathway from trend to humanitarian consequence?','Find any missing step between a development and its possible effect.'],
 ['Try another interpretation','Are there alternative interpretations of the same evidence?','Consider what would make a different explanation more convincing.'],
 ['Look for missing perspectives','Have we overlooked important populations, geographies or actors?','Ask whose experience or knowledge is absent.'],
 ['Check the scale','Are we exaggerating the severity or likelihood of impacts?','Revisit the evidence and the language used to describe uncertainty.'],
 ['Remember capacity','Have we considered the capabilities of organisations and communities expected to respond?','Examine coping, adaptation and response capacity alongside vulnerability.'],
 ['Return to the audience','Will the intended audience understand why this matters to them?','Connect the implications to the responsibilities identified at the start.']
];
export const briefFields = [ ['summary','Summary and outlook'],['consequences','Humanitarian consequences'],['actors','Key actors'],['evidence','Evidence'],['uncertainties','Uncertainties and competing interpretations'],['indicators','Indicators to watch'],['considerations','Optional audience considerations'] ];
export const categories = ['Social','Technological','Economic','Environmental','Political'];
export const directions = ['Accelerating','Continuing','Slowing','Reversing','Difficult to assess'];
export const agendaDefaults = [['Opening',10],['Scan',35],['Prioritise',30],['Shape the narrative',20],['Write',45],['Challenge and refine',30],['Breaks',10]];
